// Convert input points to CGAL points
std::vector<internal::Point_2> cgalPoints;
cgalPoints.reserve(points.size());
for (const auto& p : points) {
    cgalPoints.emplace_back(p.x(), p.y());
}

// Compute Delaunay triangulation
internal::DT dt;
dt.insert(cgalPoints.begin(), cgalPoints.end());

// Compute Voronoi diagram as dual of Delaunay triangulation
internal::VD vd(dt);

// Extract Voronoi cells
std::vector<std::vector<Point2d>> voronoiCells;
voronoiCells.reserve(points.size());

for (auto face = vd.faces_begin(); face != vd.faces_end(); ++face) {
    std::vector<Point2d> cellVertices;
    internal::Ccb_halfedge_circulator ec_start = face->ccb();
    internal::Ccb_halfedge_circulator ec = ec_start;

    do {
        if (ec->has_source()) {
            auto source = ec->source()->point();
            cellVertices.emplace_back(source.x(), source.y());
        }
    } while (++ec != ec_start);

    // Only add non-empty cells
    if (!cellVertices.empty()) {
        voronoiCells.push_back(std::move(cellVertices));
    }
}

return voronoiCells;

